def entries():
    result = {}
    for line in ENTRIES.strip().splitlines():
        key, date, claim, detail, boundary = line.split("|")
        if key in result:
            raise ValueError(f"Duplicate editorial entry: {key}")
        result[key] = {"date": date, "claim": claim, "detail": detail, "boundary": boundary}
    return result
